def move_prompts(apps, schema_editor):
    """Email prompts stop belonging to a campaign prompt: each becomes an initial or follow-up prompt (by its old
    step), names are made unique, and each campaign gets its old prompts: the step-0 prompts as its initial-email
    prompts (one per old A/B variation) and the matching prompt on each follow-up step. Prospects keep their A/B
    group as the initial-email prompt of their old variation."""
    EmailPrompt = apps.get_model("pipeline", "EmailPrompt")
    CampaignPrompt = apps.get_model("pipeline", "CampaignPrompt")
    DiscoveryCampaign = apps.get_model("pipeline", "DiscoveryCampaign")
    FollowUp = apps.get_model("pipeline", "FollowUp")
    Prospect = apps.get_model("pipeline", "Prospect")
    names = dict(CampaignPrompt.objects.values_list("id", "name"))
    seen = set()
    for prompt in EmailPrompt.objects.order_by("id"):
        name = prompt.name
        if name in seen:
            name = f"{prompt.name} ({names.get(prompt.campaign_prompt_id, prompt.campaign_prompt_id)})"[:240]
            if name in seen:
                name = f"{name} #{prompt.pk}"
        seen.add(name)
        EmailPrompt.objects.filter(pk=prompt.pk).update(name=name, kind="follow_up" if prompt.sequence else "initial")

    def best(queryset):  # the old choice order: default first, then "any opened", then oldest
        return queryset.order_by("-is_default", "opened", "id").first()

    for campaign in DiscoveryCampaign.objects.exclude(campaign_prompt=None):
        step0 = EmailPrompt.objects.filter(campaign_prompt_id=campaign.campaign_prompt_id, sequence=0)
        by_variation = {}
        for variation in sorted(set(step0.values_list("variation", flat=True))):
            by_variation[variation] = best(step0.filter(variation=variation))
        campaign.initial_email_prompts.set([prompt for prompt in by_variation.values() if prompt])
        for step in FollowUp.objects.filter(campaign=campaign):
            step.email_prompt = best(EmailPrompt.objects.filter(campaign_prompt_id=campaign.campaign_prompt_id,
                                                                sequence=step.sequence))
            step.save(update_fields=["email_prompt"])
        for prospect in Prospect.objects.filter(business__discovery_campaign=campaign, variation__isnull=False):
            prompt = by_variation.get(prospect.variation)
            if prompt is not None:
                Prospect.objects.filter(pk=prospect.pk).update(initial_email_prompt=prompt)


